import { useState } from 'react'
import { X, RefreshCw } from 'lucide-react'
import { instances as api } from '../../api/client'
import { UI } from '../../utils/strings'
import type { SdrInstance, AvailableProfile } from '../../types'

interface InstanceFormProps {
  instance: SdrInstance | null
  onClose: () => void
  onSaved: () => void
}

export default function InstanceForm({ instance, onClose, onSaved }: InstanceFormProps) {
  const [name, setName] = useState(instance?.name ?? '')
  const [url, setUrl] = useState(instance?.url ?? '')
  const [enabled, setEnabled] = useState(instance?.enabled ?? true)
  const [desiredProfile, setDesiredProfile] = useState<string | null>(instance?.desired_profile ?? null)
  const [profiles, setProfiles] = useState<AvailableProfile[]>([])
  const [loadingProfiles, setLoadingProfiles] = useState(false)
  const [saving, setSaving] = useState(false)
  const [error, setError] = useState<string | null>(null)

  const fetchProfiles = async () => {
    if (!instance) return
    setLoadingProfiles(true)
    try {
      const data = await api.profiles(instance.id)
      setProfiles(data)
    } catch (err: any) {
      setError(err.message)
    } finally {
      setLoadingProfiles(false)
    }
  }

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    setSaving(true)
    setError(null)
    try {
      if (instance) {
        await api.update(instance.id, { name, url, enabled, desired_profile: desiredProfile })
      } else {
        await api.create({ name, url, enabled, desired_profile: desiredProfile })
      }
      onSaved()
    } catch (err: any) {
      setError(err.message)
    } finally {
      setSaving(false)
    }
  }

  return (
    <div className="fixed inset-0 bg-black/60 z-50 flex items-center justify-center p-4">
      <form onSubmit={handleSubmit} className="card max-w-md w-full space-y-4">
        <div className="flex items-center justify-between">
          <h3 className="text-sm font-medium">
            {instance ? 'Instanz bearbeiten' : UI.cfg_add_instance}
          </h3>
          <button type="button" onClick={onClose} className="text-sdr-muted hover:text-sdr-text">
            <X className="w-4 h-4" />
          </button>
        </div>

        {error && <p className="text-sdr-red text-xs">{error}</p>}

        <div>
          <label className="label">{UI.cfg_name}</label>
          <input className="input w-full" value={name} onChange={e => setName(e.target.value)} required />
        </div>

        <div>
          <label className="label">{UI.cfg_url}</label>
          <input className="input w-full" value={url} onChange={e => setUrl(e.target.value)} placeholder="http://sdr-host:8073" required />
        </div>

        {instance && (
          <div>
            <label className="label">{UI.cfg_profile}</label>
            <div className="flex gap-2">
              <select
                className="input w-full"
                value={desiredProfile ?? ''}
                onChange={e => setDesiredProfile(e.target.value || null)}
              >
                <option value="">— kein Profil —</option>
                {profiles.map(p => (
                  <option key={p.id} value={p.id}>{p.name}</option>
                ))}
                {desiredProfile && !profiles.find(p => p.id === desiredProfile) && (
                  <option value={desiredProfile}>{desiredProfile}</option>
                )}
              </select>
              <button
                type="button"
                onClick={fetchProfiles}
                disabled={loadingProfiles}
                className="btn-ghost flex items-center gap-1 text-xs whitespace-nowrap"
              >
                <RefreshCw className={`w-3.5 h-3.5 ${loadingProfiles ? 'animate-spin' : ''}`} />
                {UI.cfg_fetch_profiles}
              </button>
            </div>
            {profiles.length === 0 && !loadingProfiles && (
              <p className="text-xs text-sdr-muted mt-1">{UI.cfg_no_profiles}</p>
            )}
          </div>
        )}

        <label className="flex items-center gap-2 text-sm cursor-pointer">
          <input type="checkbox" checked={enabled} onChange={e => setEnabled(e.target.checked)}
            className="accent-sdr-cyan" />
          {UI.cfg_enabled}
        </label>

        <div className="flex justify-end gap-2 pt-2">
          <button type="button" onClick={onClose} className="btn-ghost">{UI.cfg_cancel}</button>
          <button type="submit" disabled={saving} className="btn-primary">
            {saving ? UI.loading : UI.cfg_save}
          </button>
        </div>
      </form>
    </div>
  )
}

import { useState } from 'react'
import { Pencil, Trash2, Plus } from 'lucide-react'
import { instances as api } from '../../api/client'
import { UI } from '../../utils/strings'
import StatusBadge from '../shared/StatusBadge'
import ConfirmDialog from '../shared/ConfirmDialog'
import InstanceForm from './InstanceForm'
import type { SdrInstance } from '../../types'

interface InstanceListProps {
  instances: SdrInstance[]
  onRefresh: () => void
}

export default function InstanceList({ instances, onRefresh }: InstanceListProps) {
  const [showForm, setShowForm] = useState(false)
  const [editing, setEditing] = useState<SdrInstance | null>(null)
  const [deleteId, setDeleteId] = useState<number | null>(null)

  const handleDelete = async () => {
    if (deleteId == null) return
    await api.delete(deleteId)
    setDeleteId(null)
    onRefresh()
  }

  return (
    <>
      <div className="flex items-center justify-between mb-3">
        <h4 className="text-sm font-medium">{UI.cfg_instances}</h4>
        <button onClick={() => { setEditing(null); setShowForm(true) }} className="btn-primary flex items-center gap-1.5">
          <Plus className="w-3.5 h-3.5" />
          {UI.cfg_add_instance}
        </button>
      </div>

      {instances.length === 0 ? (
        <p className="text-sdr-muted text-sm py-4 text-center">{UI.dash_no_instances}</p>
      ) : (
        <div className="space-y-2">
          {instances.map(inst => (
            <div key={inst.id} className="flex items-center justify-between p-3 bg-sdr-bg rounded-lg border border-sdr-border">
              <div className="flex items-center gap-3 min-w-0">
                <StatusBadge active={inst.enabled} activeText={UI.cfg_enabled} inactiveText="Deaktiviert" />
                <div className="min-w-0">
                  <p className="text-sm font-medium truncate">{inst.name}</p>
                  <p className="text-xs text-sdr-muted truncate">{inst.url}</p>
                </div>
              </div>
              <div className="flex items-center gap-1 shrink-0">
                <button
                  onClick={() => { setEditing(inst); setShowForm(true) }}
                  className="p-1.5 text-sdr-muted hover:text-sdr-text transition-colors"
                  title={UI.cfg_edit}
                >
                  <Pencil className="w-3.5 h-3.5" />
                </button>
                <button
                  onClick={() => setDeleteId(inst.id)}
                  className="p-1.5 text-sdr-muted hover:text-sdr-red transition-colors"
                  title={UI.cfg_delete}
                >
                  <Trash2 className="w-3.5 h-3.5" />
                </button>
              </div>
            </div>
          ))}
        </div>
      )}

      {showForm && (
        <InstanceForm
          instance={editing}
          onClose={() => setShowForm(false)}
          onSaved={() => { setShowForm(false); onRefresh() }}
        />
      )}

      <ConfirmDialog
        open={deleteId != null}
        message={UI.confirm_delete}
        onConfirm={handleDelete}
        onCancel={() => setDeleteId(null)}
      />
    </>
  )
}
